import React, { useState, useEffect } from 'react';
import styles from './App.module.css';
import HeroSection from './components/HeroSection/HeroSection';
import Education from './components/Education/Education';
import Skills from './components/Skills/Skills';
import Thesis from './components/Thesis/Thesis';
import Projects from './components/Projects/Projects';
import Certifications from './components/Certifications/Certifications';
import Extracurricular from './components/Extracurricular/Extracurricular';
import SoftSkills from './components/SoftSkills/SoftSkills';
import Contact from './components/Contact/Contact';
import TerminalCursor from './components/TerminalCursor/TerminalCursor';

function App() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeSection, setActiveSection] = useState('hero');
  const [scrolled, setScrolled] = useState(false);

  const navItems = [
    { id: 'hero', label: 'home', icon: '🏠' },
    { id: 'education', label: 'education', icon: '🎓' },
    { id: 'skills', label: 'skills', icon: '⚡' },
    { id: 'thesis', label: 'thesis', icon: '📚' },
    { id: 'projects', label: 'projects', icon: '💻' },
    { id: 'certifications', label: 'certifications', icon: '📜' },
    { id: 'extracurricular', label: 'activities', icon: '🎯' },
    { id: 'softskills', label: 'soft skills', icon: '💭' },
    { id: 'contact', label: 'contact', icon: '📧' }
  ];

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      const offset = 70; // Height of header
      const elementPosition = element.offsetTop - offset;
      window.scrollTo({
        top: elementPosition,
        behavior: 'smooth'
      });
      setMobileMenuOpen(false);
    }
  };

  // Track active section on scroll
  useEffect(() => {
    const handleScroll = () => {
      // Update scrolled state for header styling
      setScrolled(window.scrollY > 50);
      
      // Track active section
      const scrollPosition = window.scrollY + 100;
      
      for (const item of navItems) {
        const section = document.getElementById(item.id);
        if (section) {
          const sectionTop = section.offsetTop;
          const sectionBottom = sectionTop + section.offsetHeight;
          
          if (scrollPosition >= sectionTop && scrollPosition < sectionBottom) {
            if (activeSection !== item.id) {
              setActiveSection(item.id);
            }
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll();
    
    return () => window.removeEventListener('scroll', handleScroll);
  }, [activeSection]);

  // Close mobile menu on resize
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth > 768 && mobileMenuOpen) {
        setMobileMenuOpen(false);
      }
    };
    
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [mobileMenuOpen]);

  // Prevent body scroll when mobile menu is open
  useEffect(() => {
    if (mobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [mobileMenuOpen]);

  return (
    <div className={styles.app}>
      <TerminalCursor />
      
      <header className={`${styles.header} ${scrolled ? styles.scrolled : ''}`}>
        <div className={styles.terminalBar}>
          <div className={styles.logo}>
            <div className={styles.terminalDots}>
              <span className={styles.dot}></span>
              <span className={styles.dot}></span>
              <span className={styles.dot}></span>
            </div>
            <div className={styles.terminalPath}>
              <span className={styles.user}>safayet</span>
              <span className={styles.at}>@</span>
              <span className={styles.host}>portfolio</span>
              <span className={styles.tilde}>~</span>
              <span className={styles.cursor}>█</span>
            </div>
          </div>
          
          {/* Desktop Navigation */}
          <nav className={styles.desktopNav}>
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => scrollToSection(item.id)}
                className={`${styles.navItem} ${activeSection === item.id ? styles.active : ''}`}
              >
                <span className={styles.promptSign}>$</span>
                <span>{item.label}</span>
              </button>
            ))}
          </nav>

          {/* Mobile Menu Button */}
          <button 
            className={`${styles.mobileMenuBtn} ${mobileMenuOpen ? styles.open : ''}`}
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            aria-label="Toggle menu"
          >
            <span></span>
            <span></span>
            <span></span>
          </button>
        </div>

        {/* Mobile Navigation Overlay */}
        <div className={`${styles.mobileOverlay} ${mobileMenuOpen ? styles.open : ''}`} onClick={() => setMobileMenuOpen(false)}></div>
        
        {/* Mobile Navigation Menu */}
        <div className={`${styles.mobileNav} ${mobileMenuOpen ? styles.mobileNavOpen : ''}`}>
          <div className={styles.mobileNavHeader}>
            <span className={styles.mobilePrompt}>$ cd /navigation</span>
            <button className={styles.closeBtn} onClick={() => setMobileMenuOpen(false)}>✕</button>
          </div>
          <div className={styles.mobileNavItems}>
            {navItems.map((item, index) => (
              <button
                key={item.id}
                onClick={() => scrollToSection(item.id)}
                className={`${styles.mobileNavItem} ${activeSection === item.id ? styles.active : ''}`}
                style={{ animationDelay: `${index * 0.05}s` }}
              >
                <span className={styles.mobileIcon}>{item.icon}</span>
                <span className={styles.mobilePrompt}>$</span>
                <span className={styles.mobileLabel}>{item.label}</span>
                <span className={styles.mobileArrow}>→</span>
              </button>
            ))}
          </div>
          <div className={styles.mobileNavFooter}>
            <span className={styles.promptSign}>$</span>
            <span>echo "Navigate to explore"</span>
          </div>
        </div>
      </header>

      <main className={styles.main}>
        <HeroSection />
        <Education />
        <Skills />
        <Thesis />
        <Projects />
        <Certifications />
        <Extracurricular />
        <SoftSkills />
        <Contact />
      </main>

      <footer className={styles.footer}>
        <div className={styles.footerContent}>
          <span className={styles.promptSign}>$</span>
          <span className={styles.footerText}>echo "© 2026 Safayet Hossain Sawom | All rights reserved"</span>
          <span className={styles.blinkingCursor}>█</span>
        </div>
      </footer>
    </div>
  );
}

export default App;
